std::vector<Point2d> intersections;
size_t n = segments.size();

for (size_t i = 0; i < n; ++i) {
    const Segment2d& seg1 = segments[i];
    const Point2d& p1From = seg1.p1();
    const Point2d& p1To   = seg1.p2();
    CK_Segment_2 cgalSeg1(
        CK_Point_2(p1From.x(), p1From.y()),
        CK_Point_2(p1To.x(),   p1To.y())
    );

    for (size_t j = i + 1; j < n; ++j) {
        const Segment2d& seg2 = segments[j];
        const Point2d& p2From = seg2.p1();
        const Point2d& p2To   = seg2.p2();
        CK_Segment_2 cgalSeg2(
            CK_Point_2(p2From.x(), p2From.y()),
            CK_Point_2(p2To.x(),   p2To.y())
        );

        auto result = CGAL::intersection(cgalSeg1, cgalSeg2);
        if (result) {
            if (const CK_Point_2* ip = boost::get<CK_Point_2>(&*result)) {
                intersections.emplace_back(ip->x(), ip->y());
            } else if (const CK_Segment_2* iseg = boost::get<CK_Segment_2>(&*result)) {
                intersections.emplace_back(iseg->source().x(), iseg->source().y());
                intersections.emplace_back(iseg->target().x(), iseg->target().y());
            }
        }
    }
}

// Remove duplicate points (considering a small epsilon)
std::sort(intersections.begin(), intersections.end(),
    [](const Point2d& a, const Point2d& b) {
        if (a.x() < b.x()) return true;
        if (a.x() > b.x()) return false;
        return a.y() < b.y();
    });

const double eps = 1e-9;
intersections.erase(
    std::unique(intersections.begin(), intersections.end(),
        [eps](const Point2d& a, const Point2d& b) {
            return std::abs(a.x() - b.x()) < eps && std::abs(a.y() - b.y()) < eps;
        }),
    intersections.end());

return intersections;

